function debugFrontier(s,action){if(!isDebug(s))return {ok:false,reason:'仅调试航程可用'};if(s.stage<6)return {ok:false,reason:'先研究 T6，建岛与升级仍需真实前置'};if(s.mode==='failed')return {ok:false,reason:'当前已失守，请先重试或新建调试航程'};const liveTitan=[...s.enemies,...s.spawnBacklog].some(e=>e.kind==='abyssTitan'&&e.hp>0);if(action==='start'){if(liveTitan)return {ok:false,reason:'已有超级海兽，请先击败或清空敌人再重开测试'};s.frontier={...newFrontier(),levels:{...s.frontier.levels}};s.maxHull=hullCap(s);s.hull=Math.min(s.hull,s.maxHull);s.shield=Math.min(s.shield,shieldCap(s));s.victory=true;return startFrontier(s);}if(action==='boss'){if(liveTitan)return {ok:false,reason:'已有一只超级海兽，请先击败或清空敌人'};if(s.enemies.length+s.spawnBacklog.length>=MAX_ENEMIES+DEBUG_MAX_BACKLOG)return {ok:false,reason:'敌人队列已满，请先清理'};Object.assign(s.frontier,{active:true,completed:false,endless:false,bossSpawned:false,bossDefeated:false,nextWave:s.frontier.elapsed+18});delete s.frontier.run;s.maxHull=hullCap(s);s.hull=Math.min(s.hull,s.maxHull);s.shield=Math.min(s.shield,shieldCap(s));s.mode='playing';s.victory=true;s.nextWave=Infinity;s.nextStorm=Infinity;s.storm=0;spawnFrontier(s,true);}else{if(!s.frontier.active)return {ok:false,reason:'先开启终章测试'};if(!spawnFrontier(s))return {ok:false,reason:'敌人队列已满，请先清理'};}return {ok:true,reason:'终章测试已执行；资源、伤害与暂停开关照常，正常存档不变'};}
